/// How a stored narrative was produced: a trip's `aiGeneratedSummary` or a
/// year's Wrapped narrative.
///
/// Persisted as `String` via `Trip.summarySourceRaw` — same pattern
/// as `DataSource`: forward-compatible, CloudKit-safe.
nonisolated enum SummarySource: String, Codable, CaseIterable, Sendable {
    /// Generated by Apple's on-device Foundation Models (Apple Intelligence).
    case foundationModels = "foundationModels"

    /// Deterministic template fallback when FM is unavailable or fails.
    case deterministic = "deterministic"

    static func decode(_ raw: String) -> SummarySource {
        SummarySource(rawValue: raw) ?? .deterministic
    }
}
